const b = $input.first().json.body || {};
const mime = b.mimeType || 'image/jpeg';
const img = b.imageBase64 || '';
const sys = 'Kamu OCR nota belanja Indonesia. Dari foto nota, keluarkan HANYA JSON object berbentuk {"items":[{"name":string,"qty":number,"unit":string|null,"unitPrice":number,"supplier":string|null,"notaDate":"YYYY-MM-DD"|null}]}. unitPrice = harga satuan dalam rupiah, angka saja tanpa titik/koma. Jika sebuah field tak ada di nota, isi null. Jangan menambah teks lain.';
return [{ json: { body: {
  model: 'gpt-4o',
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: sys },
    { role: 'user', content: [
      { type: 'text', text: 'Ambil daftar item dari nota ini.' },
      { type: 'image_url', image_url: { url: `data:${mime};base64,${img}` } }
    ] }
  ]
} } }];

const c = $input.first().json;
const txt = (c.choices && c.choices[0] && c.choices[0].message && c.choices[0].message.content) || '{}';
let o; try { o = JSON.parse(txt); } catch (e) { o = { items: [] }; }
const items = Array.isArray(o.items) ? o.items : [];
return [{ json: { items } }];
